static inline void qspi_ll_io_write(qspi_hw_t *hw, const void *data, uint32_t data_len)
{
	uint32_t fifo_num = 0;

	if(0 == (data_len % 4)) {
		fifo_num = data_len / 4;
	} else 	{
		fifo_num = (data_len / 4) + 1;
	}

	for(uint32_t i = 0; i < fifo_num; i++) {
		*((uint32_t *)(hw->fifo_data) + i) = *((uint32_t *)data + i);
	}
}
