/****************************************************************************
 * board/beken/chips/bk7258/bk7258_ldo33.c
 *
 * Reference-counted control of the shared LDO33_EN rail (GPIO52).  See
 * include/bk7258_ldo33.h for the schematic evidence that this rail is
 * board-wide rather than motor-specific.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>

#include <nuttx/irq.h>
#include <nuttx/spinlock.h>

#include "bk7258_gpio.h"
#include "bk7258_ldo33.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static unsigned int g_ldo33_refs;
static bool g_ldo33_configured;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

unsigned int bk7258_ldo33_request(void)
{
  irqstate_t flags;
  unsigned int refs;

  flags = enter_critical_section();

  if (!g_ldo33_configured)
    {
      /* First consumer: take the pad away from any second function and
       * drive it high in one step.  Doing this on the first *request*
       * rather than in a separate init hook means the rail can never be
       * observed configured-but-off, which is the state that left the
       * panel dark.
       */

      bk7258_gpio_output(BK7258_LDO33_EN_GPIO, true);
      g_ldo33_configured = true;
    }
  else if (g_ldo33_refs == 0)
    {
      bk7258_gpio_write(BK7258_LDO33_EN_GPIO, true);
    }

  refs = ++g_ldo33_refs;
  leave_critical_section(flags);

  return refs;
}

unsigned int bk7258_ldo33_release(void)
{
  irqstate_t flags;
  unsigned int refs;

  flags = enter_critical_section();

  if (g_ldo33_refs > 0 && --g_ldo33_refs == 0)
    {
      bk7258_gpio_write(BK7258_LDO33_EN_GPIO, false);
    }

  refs = g_ldo33_refs;
  leave_critical_section(flags);

  return refs;
}

unsigned int bk7258_ldo33_refcount(void)
{
  return g_ldo33_refs;
}

/****************************************************************************
 * board/beken/chips/bk7258/bk7258_qspi.c
 *
 * 4-wire MCU-SPI LCD transport built on the BK7258 QSPI1 controller.
 * Register layout source: bk_avdk_smp release/v3.1.1
 * ap/middleware/soc/bk7258_ap/soc/qspi_struct.h and hal/qspi_ll.h.
 * Protocol source: ap/middleware/driver/lcd/lcd_spi_driver.c.
 *
 * ---------------------------------------------------------------------
 * 2026-08-10 rewrite: wrong panel class
 * ---------------------------------------------------------------------
 * The previous version of this file spoke the *QSPI panel* protocol from
 * lcd_qspi_driver.c: a 4-byte {0x02, 0x00, reg, 0x00} header in cmd_c_h,
 * payload in cmd_c_l, and a {0x02, 0x00, 0x2C, 0x00} header in front of
 * the pixel burst.  GC9D01 is not that kind of panel.  It sits in
 * bk_avdk_smp's lcd/**spi**/ directory, its device table declares
 * .type = LCD_TYPE_SPI, and lcd_spi_driver.c drives it as plain 4-wire
 * MCU SPI:
 *
 *   bk_lcd_spi_send_cmd():  DC low,  then the bare opcode byte
 *   bk_lcd_spi_send_data(): DC high, then the bare parameter bytes
 *
 * with the bytes packed into cmd_c_h (not cmd_c_l) and cmd_c_cfg1 set to
 * 0x3 << (data_len * 2) to mark the end of the transfer.  There is no
 * header byte of any kind.
 *
 * That mismatch is why every command "succeeded" while the panel stayed
 * dark: cmd_start_done only reports that the controller finished shifting
 * out whatever it was told to, and a well-formed burst of the wrong bytes
 * looks identical to a correct one from the register side.  The panel was
 * being fed 0x02 as its opcode over and over, with D/C never asserted --
 * and D/C was not merely unused, it was actively pinmuxed to QSPI1_IO1
 * (see below), so the panel saw a data line wiggling where it expected a
 * command/data select.
 *
 * ---------------------------------------------------------------------
 * Pin routing (AIDK_AI玩具开发板_原理图.pdf)
 * ---------------------------------------------------------------------
 * Sheet 2/6's main-chip pin table gives the net for each pad, and sheet
 * 5/6's LCD1 footprint -- the one labelled 单屏 (single screen), as
 * opposed to LCD2 labelled 双屏 -- gives what each net connects to on the
 * panel:
 *
 *   chip pin 36 = P2 = QSPI1_CLK  -> LCD_QSPI_CLK -> panel SCL
 *   chip pin 35 = P3 = QSPI1_CSN  -> LCD_QSPI_CS  -> panel CS
 *   chip pin 34 = P4 = QSPI1_IO0  -> LCD_QSPI_D0  -> panel SDA
 *   chip pin 33 = P5 = QSPI1_IO1  -> LCD_QSPI_D1  -> panel D/C   (!)
 *   chip pin 65 = P45            -> LCD_RST      -> panel RESET
 *
 * So only three of the four QSPI1 signals belong to the controller.  The
 * board designer's net names are QSPI-flavoured ("LCD_QSPI_D1") but the
 * panel end of that same net is the D/C input, so GPIO5 must stay a plain
 * GPIO output.  This also settles the earlier uncertainty recorded in
 * hardware/bk7258_memorymap.h: QSPI1 (not QSPI0) really is the right
 * controller here, and the net names really do line up with the SoC's own
 * QSPI1 function assignments in gpio_map.h -- GPIO2/3/4/5 carry
 * QSPI1_CLK/CSN/IO0/IO1 at function-select index 6.
 *
 * ---------------------------------------------------------------------
 * Clocking
 * ---------------------------------------------------------------------
 * The panel clock is NOT config.clk_rate.  bk_qspi_init()
 * (ap/middleware/driver/qspi/qspi_driver.c) programs the source mux and
 * pre-divider through sysctrl and leaves clk_rate at 0 for every LCD
 * path; see hardware/bk7258_sysctrl.h for the field citations.  The
 * previous version of this file wrote clk_rate = 8 instead, which changed
 * SCK to an unintended frequency (harmless on its own, but it meant the
 * "60MHz" in the comments was not what the hardware was doing).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

#include "arm_internal.h"
#include "hardware/bk7258_memorymap.h"
#include "hardware/bk7258_sysctrl.h"
#include "bk7258_gpio.h"
#include "bk7258_qspi.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define QSPI1_CLK_PIN               2u
#define QSPI1_CSN_PIN               3u
#define QSPI1_IO0_PIN               4u
#define QSPI1_PINMUX_FUNCTION       6u

#define QSPI_REG(offset)           (BK7258_QSPI1_BASE + (offset))

#define QSPI_GLB_CTRL              QSPI_REG(0x08u)
#define QSPI_GLB_CTRL_SOFT_RESET   (1u << 0)

/* cmd_a_* is only used for its cfg2 register, which selects the transfer
 * shape used by the memory-mapped data window (REG_0x0b, byte 0x2c).
 */

#define QSPI_CMD_A_CFG2            QSPI_REG(0x2cu)

#define QSPI_CMD_C_L               QSPI_REG(0x40u)
#define QSPI_CMD_C_H               QSPI_REG(0x44u)
#define QSPI_CMD_C_CFG1            QSPI_REG(0x48u)
#define QSPI_CMD_C_CFG2            QSPI_REG(0x4cu)

#define QSPI_STATUS                QSPI_REG(0x70u)
#define QSPI_STATUS_CMD_START_DONE (1u << 2)

#define QSPI_STATUS_CLR                 QSPI_REG(0x6cu)
#define QSPI_STATUS_CLR_CMD_START_DONE  (1u << 2)

#define QSPI_CMD_START_BIT         (1u << 0)

/* config, REG_0x18 (qspi_struct.h) */

#define QSPI_CONFIG                     QSPI_REG(0x60u)
#define QSPI_CONFIG_QSPI_EN             (1u << 0)
#define QSPI_CONFIG_IO2_IO3_MODE        (1u << 3)
#define QSPI_CONFIG_FORCE_SPI_CS_LOW    (1u << 6)
#define QSPI_CONFIG_CLK_RATE_SHIFT      8u
#define QSPI_CONFIG_CLK_RATE_MASK       (0xffu << QSPI_CONFIG_CLK_RATE_SHIFT)
#define QSPI_CONFIG_DISABLE_CMD_SCK     (1u << 16)
#define QSPI_CONFIG_IO_CPU_MEM_SEL      (1u << 22)

/* Memory-mapped data window of the QSPI1 controller
 * (LCD_QSPI1_DATA_ADDR, ap/include/driver/lcd_qspi_types.h).  With
 * config.io_cpu_mem_sel set, every write into this window is streamed out
 * of the QSPI data line.
 */

#define QSPI1_DATA_WINDOW               0x68000000u

/* cmd_a_cfg2 value installed once at init, copied verbatim from
 * lcd_spi_driver_init_with_qspi()'s
 * qspi_hal_set_cmd_a_cfg2(hal, 0x80000000) under
 * CONFIG_LCD_SPI_REFRESH_WITH_QSPI_MAPPING_MODE.  Decoded against
 * qspi_struct.h's cmd_a_cfg2 bitfields that is cmd_mode = 2 (bits 31:30)
 * with data_line = 0 (bits 15:14), i.e. single-line data -- which is what
 * a 4-wire SPI panel needs, since only SDA is wired.
 */

#define QSPI_CMD_A_CFG2_MAPPING_MODE    0x80000000u

/* Source clock 480MHz / (1 + 7) = 60MHz, matching LCD_QSPI_60M as
 * requested by lcd_spi_gc9d01_config.clk.
 */

#define QSPI1_SRC_CLK_DIV_60M           7u

/* TX FIFO window, REG_0x40.. (qspi_struct.h's fifo_data[61]).  The vendor
 * driver chunks at 0x100 bytes, which is larger than the 244-byte FIFO;
 * capping at the real FIFO size instead avoids writing past fifo_data[]
 * into the registers that follow it.  Nothing in the GC9D01 command table
 * comes close to either bound (the longest payload is 32 bytes), so this
 * only matters for the pixel path, which does not use the FIFO at all.
 */

#define QSPI_FIFO_DATA                  QSPI_REG(0x100u)
#define QSPI_FIFO_MAX_BYTES             (61u * 4u)

#define QSPI_CFG1_FIFO_PAYLOAD          0x300u
#define QSPI_CFG2_DATA_LEN_SHIFT        2u
#define QSPI_CMD_LINE_MARK              0x3u

/* Matches qspi_ll_wait_cmd_done()'s 10000-iteration bound
 * (ap/middleware/soc/bk7258_ap/hal/qspi_ll.h) instead of looping forever,
 * so a pinmux or wiring problem produces a diagnosable timeout rather than
 * an unrecoverable hang.
 */

#define QSPI_WAIT_DONE_MAX_ITER    10000

/* Settle time between the last window write and releasing CS, copied from
 * bk_lcd_spi_wait_display_complete()'s bk_delay_us(15).
 */

#define QSPI_FRAME_TAIL_DELAY_US   15

#define GC9D01_CMD_RAMWR           0x2Cu

/****************************************************************************
 * Private Data
 ****************************************************************************/

static unsigned int g_dc_pin;
static bool g_initialized;
static bool g_cmd_traced;
static uint32_t g_frames;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static bool bk7258_lcd_spi_wait_done(void)
{
  int i;

  for (i = 0; i < QSPI_WAIT_DONE_MAX_ITER; i++)
    {
      if ((getreg32(QSPI_STATUS) & QSPI_STATUS_CMD_START_DONE) != 0)
        {
          break;
        }

      up_udelay(1);
    }

  /* Clear cmd_start_done (write 1 then 0), matching qspi_ll_wait_cmd_done()
   * -- required so a stale "done" flag from this command does not make the
   * next command's wait loop return immediately.
   */

  modifyreg32(QSPI_STATUS_CLR, 0, QSPI_STATUS_CLR_CMD_START_DONE);
  modifyreg32(QSPI_STATUS_CLR, QSPI_STATUS_CLR_CMD_START_DONE, 0);

  return i < QSPI_WAIT_DONE_MAX_ITER;
}

/****************************************************************************
 * Name: bk7258_lcd_spi_xfer_short
 *
 * Description:
 *   Shifts out 1..4 bytes through the cmd_c channel, byte 0 first.  This
 *   is lcd_spi_send_data_with_qspi_cmd_c(): all four registers are cleared
 *   first (which also drops any stale data_len left in cfg2 by a previous
 *   FIFO transfer), the bytes are packed little-endian into cmd_c_h so
 *   that cmd1 == data[0], and cfg1 marks the first *unused* byte slot with
 *   wire-mode 3.
 *
 ****************************************************************************/

static bool bk7258_lcd_spi_xfer_short(const uint8_t *data, uint32_t len)
{
  uint32_t value = 0;
  uint32_t i;

  putreg32(0, QSPI_CMD_C_L);
  putreg32(0, QSPI_CMD_C_H);
  putreg32(0, QSPI_CMD_C_CFG1);
  putreg32(0, QSPI_CMD_C_CFG2);

  for (i = 0; i < len; i++)
    {
      value |= ((uint32_t)data[i]) << (i * 8);
    }

  putreg32(value, QSPI_CMD_C_H);
  putreg32(QSPI_CMD_LINE_MARK << (len * 2u), QSPI_CMD_C_CFG1);

  if (!g_cmd_traced)
    {
      /* One-shot trace of the very first transfer.  The whole framing fix
       * lives in these three registers, so their read-back values are the
       * evidence that a bare opcode -- not a QSPI header -- is going out.
       */

      g_cmd_traced = true;
      printf("bk7258_lcd_spi: first xfer: cmd_c_h=0x%08x cmd_c_l=0x%08x "
             "cfg1=0x%08x cfg2=0x%08x len=%u\n",
             (unsigned int)getreg32(QSPI_CMD_C_H),
             (unsigned int)getreg32(QSPI_CMD_C_L),
             (unsigned int)getreg32(QSPI_CMD_C_CFG1),
             (unsigned int)getreg32(QSPI_CMD_C_CFG2),
             (unsigned int)len);
    }

  modifyreg32(QSPI_CMD_C_CFG2, 0, QSPI_CMD_START_BIT);

  return bk7258_lcd_spi_wait_done();
}

/****************************************************************************
 * Name: bk7258_lcd_spi_xfer_fifo
 *
 * Description:
 *   Shifts out the first 4 bytes through cmd_c_h and the next 'fifo_len'
 *   bytes through the TX FIFO, as lcd_spi_send_data_with_qspi_indirect_
 *   mode()'s long branch does.  Bytes are assembled a byte at a time so an
 *   unaligned source pointer is safe (the payload of a command table entry
 *   generally is not word aligned).
 *
 ****************************************************************************/

static bool bk7258_lcd_spi_xfer_fifo(const uint8_t *data, uint32_t fifo_len)
{
  uint32_t words = (fifo_len + 3u) / 4u;
  uint32_t value;
  uint32_t i;

  value = ((uint32_t)data[0]) |
          ((uint32_t)data[1] << 8) |
          ((uint32_t)data[2] << 16) |
          ((uint32_t)data[3] << 24);

  putreg32(value, QSPI_CMD_C_H);
  putreg32(QSPI_CFG1_FIFO_PAYLOAD, QSPI_CMD_C_CFG1);
  putreg32(fifo_len << QSPI_CFG2_DATA_LEN_SHIFT, QSPI_CMD_C_CFG2);

  for (i = 0; i < words; i++)
    {
      uint32_t word = 0;
      uint32_t b;

      for (b = 0; b < 4u; b++)
        {
          uint32_t idx = i * 4u + b;

          if (idx < fifo_len)
            {
              word |= ((uint32_t)data[4u + idx]) << (b * 8);
            }
        }

      putreg32(word, QSPI_FIFO_DATA + i * 4u);
    }

  modifyreg32(QSPI_CMD_C_CFG2, 0, QSPI_CMD_START_BIT);

  return bk7258_lcd_spi_wait_done();
}

static bool bk7258_lcd_spi_xfer(const uint8_t *data, uint32_t len)
{
  uint32_t remain = len;
  const uint8_t *p = data;

  while (remain > 0)
    {
      uint32_t fifo_len;

      if (remain <= 4u)
        {
          return bk7258_lcd_spi_xfer_short(p, remain);
        }

      fifo_len = remain - 4u;
      if (fifo_len > QSPI_FIFO_MAX_BYTES)
        {
          fifo_len = QSPI_FIFO_MAX_BYTES;
        }

      if (!bk7258_lcd_spi_xfer_fifo(p, fifo_len))
        {
          return false;
        }

      p += 4u + fifo_len;
      remain -= 4u + fifo_len;
    }

  return true;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void bk7258_lcd_spi_init(unsigned int dc_pin)
{
  g_dc_pin = dc_pin;

  /* 1. Module clock gate.  Without this the controller's command state
   * machine has no clock and cmd_start_done never asserts (see
   * hardware/bk7258_sysctrl.h).
   */

  modifyreg32(BK7258_SYS_DEVCLK_EN, 0, BK7258_QSPI1_MODULE_CLK_EN);

  /* 2. Source clock: 480MHz / 8 = 60MHz, the divider path bk_qspi_init()
   * uses.  config.clk_rate stays 0 (cleared in step 4).
   */

  modifyreg32(BK7258_SYS_CPU26M_WDT_CLKDIV,
              BK7258_QSPI1_CKDIV_MASK,
              (QSPI1_SRC_CLK_DIV_60M << BK7258_QSPI1_CKDIV_SHIFT) |
              BK7258_QSPI1_CKSEL_480M);

  /* 3. Pinmux CLK/CSN/IO0 only.  IO1's pad (GPIO5) is the panel's D/C
   * line and must stay a plain GPIO -- handing it to the controller is
   * what left the panel unable to tell commands from data.  Idle high =
   * "data", matching lcd_spi_device_gpio_init()'s initial state.
   */

  bk7258_gpio_set_function(QSPI1_CLK_PIN, QSPI1_PINMUX_FUNCTION);
  bk7258_gpio_set_function(QSPI1_CSN_PIN, QSPI1_PINMUX_FUNCTION);
  bk7258_gpio_set_function(QSPI1_IO0_PIN, QSPI1_PINMUX_FUNCTION);
  bk7258_gpio_output(g_dc_pin, true);

  /* 4. Controller enable, qspi_ll_init_common(): qspi_en + io2_io3_mode.
   * io2_io3_mode makes IO2/IO3 driven from config.io2/io3 instead of by
   * the shifter, which is correct when only one data line is wired.
   */

  modifyreg32(QSPI_CONFIG, QSPI_CONFIG_CLK_RATE_MASK,
              QSPI_CONFIG_QSPI_EN | QSPI_CONFIG_IO2_IO3_MODE);

  /* 5. Soft-reset pulse.  Order and final state copied from
   * lcd_spi_driver_init_with_qspi(): disable (0), delay, enable (1).  The
   * previous version of this file did the opposite and left the bit at 0.
   */

  modifyreg32(QSPI_GLB_CTRL, QSPI_GLB_CTRL_SOFT_RESET, 0);
  up_udelay(10);
  modifyreg32(QSPI_GLB_CTRL, 0, QSPI_GLB_CTRL_SOFT_RESET);

  /* 6. Data-window transfer shape for the pixel path. */

  putreg32(QSPI_CMD_A_CFG2_MAPPING_MODE, QSPI_CMD_A_CFG2);

  g_initialized = true;

  printf("bk7258_lcd_spi: init: devclk_en=0x%08x clkdiv=0x%08x "
         "config=0x%08x glb_ctrl=0x%08x cmd_a_cfg2=0x%08x dc=GPIO%u\n",
         (unsigned int)getreg32(BK7258_SYS_DEVCLK_EN),
         (unsigned int)getreg32(BK7258_SYS_CPU26M_WDT_CLKDIV),
         (unsigned int)getreg32(QSPI_CONFIG),
         (unsigned int)getreg32(QSPI_GLB_CTRL),
         (unsigned int)getreg32(QSPI_CMD_A_CFG2),
         (unsigned int)g_dc_pin);
}

bool bk7258_lcd_spi_write_cmd(uint8_t cmd)
{
  if (!g_initialized)
    {
      return false;
    }

  bk7258_gpio_write(g_dc_pin, false);

  return bk7258_lcd_spi_xfer(&cmd, 1u);
}

bool bk7258_lcd_spi_write_data(const uint8_t *data, uint32_t len)
{
  if (!g_initialized || data == NULL || len == 0)
    {
      return false;
    }

  bk7258_gpio_write(g_dc_pin, true);

  return bk7258_lcd_spi_xfer(data, len);
}

bool bk7258_lcd_spi_write_cmd_data(uint8_t cmd, const uint8_t *data,
                                   uint32_t len)
{
  if (!bk7258_lcd_spi_write_cmd(cmd))
    {
      return false;
    }

  if (len == 0)
    {
      return true;
    }

  return bk7258_lcd_spi_write_data(data, len);
}

bool bk7258_lcd_spi_write_frame(const void *frame, size_t len)
{
  const uint32_t *src = frame;
  size_t words = len / 4u;
  size_t i;

  if (!g_initialized || frame == NULL || len == 0 || (len & 3u) != 0)
    {
      return false;
    }

  /* RAMWR goes out as an ordinary DC-low command; CS is allowed to
   * deassert afterwards, exactly as bk_lcd_spi_frame_display() does.
   */

  if (!bk7258_lcd_spi_write_cmd(GC9D01_CMD_RAMWR))
    {
      return false;
    }

  bk7258_gpio_write(g_dc_pin, true);

  /* lcd_spi_quad_write_start(): park the command channel, hold CS low for
   * the whole burst, hand the data line to the memory-mapped window and
   * stop the command path from generating SCK.
   */

  putreg32(0, QSPI_CMD_C_L);
  putreg32(0, QSPI_CMD_C_H);
  putreg32(0, QSPI_CMD_C_CFG1);
  putreg32(0, QSPI_CMD_C_CFG2);

  modifyreg32(QSPI_CONFIG, 0, QSPI_CONFIG_FORCE_SPI_CS_LOW);
  modifyreg32(QSPI_CONFIG, 0, QSPI_CONFIG_IO_CPU_MEM_SEL);
  modifyreg32(QSPI_CONFIG, 0, QSPI_CONFIG_DISABLE_CMD_SCK);

  if (g_frames < 2)
    {
      printf("bk7258_lcd_spi: frame %u: config=0x%08x words=%u src=%p "
             "first_px=0x%04x\n", (unsigned int)g_frames,
             (unsigned int)getreg32(QSPI_CONFIG), (unsigned int)words,
             frame, (unsigned int)(src[0] & 0xffff));
    }

  /* CPU-driven copy.  The controller back-pressures the AHB write when its
   * FIFO is full, so this self-throttles to the wire rate; 160x160 RGB565
   * measured ~23ms on the bus.  DMA can replace this later without
   * changing the function's contract.
   */

  for (i = 0; i < words; i++)
    {
      putreg32(src[i], QSPI1_DATA_WINDOW);
    }

  up_udelay(QSPI_FRAME_TAIL_DELAY_US);

  /* lcd_spi_quad_write_stop(), same order as the reference. */

  modifyreg32(QSPI_CONFIG, QSPI_CONFIG_DISABLE_CMD_SCK, 0);
  modifyreg32(QSPI_CONFIG, QSPI_CONFIG_FORCE_SPI_CS_LOW, 0);
  modifyreg32(QSPI_CONFIG, QSPI_CONFIG_IO_CPU_MEM_SEL, 0);

  g_frames++;
  return true;
}

uint32_t bk7258_lcd_spi_frame_count(void)
{
  return g_frames;
}

