/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_gc9d01.c
 *
 * GC9D01 160x160 round LCD bring-up (4-wire MCU SPI over QSPI1).
 *
 * Init command table copied verbatim -- all 50 entries -- from
 * bk_avdk_smp release/v3.1.1
 * ap/components/bk_peripheral/src/lcd/spi/lcd_spi_gc9d01.c
 * (gc9d01_init_cmds).  The bring-up sequence follows bk_lcd_spi_init() in
 * ap/middleware/driver/lcd/lcd_spi_driver.c.
 *
 * ---------------------------------------------------------------------
 * 2026-08-10: why the panel was dark even though the bus was busy
 * ---------------------------------------------------------------------
 * The boot log showed the whole software chain reporting success --
 * 48 init commands sent with no timeout, "display on", a test pattern
 * drawn, and 51200 bytes clocked out in 23ms -- with nothing on the glass.
 * Four independent causes, each on its own sufficient to produce a black
 * screen, were found by cross-checking the schematic against the vendor
 * driver:
 *
 *  1. Panel power was off.  The LCD1 connector's VDD (pin 5) and LEDA
 *     (pin 4) both come from LDO_3V3, whose enable is the LDO33_EN net =
 *     GPIO52.  Nothing here ever asserted it -- worse, bk7258_pwm.c owned
 *     GPIO52 as "BK7258_MOTOR_LDO_GPIO" and drove it *low* in its setup
 *     path, which runs earlier in bk7258_bringup() than the display does.
 *     GPIO52 is now a reference-counted shared rail (bk7258_ldo33.c).
 *
 *  2. Backlight was off.  LEDK comes from the LCD_BL net, switched by Q3
 *     (MMBT3904, 1K base resistor, 10K pulldown) from LCD_BL_PWM =
 *     GPIO25.  A GC9D01 module is a transmissive TFT: with the backlight
 *     off the GRAM contents are invisible no matter how correct they are.
 *
 *  3. No D/C line.  See bk7258_qspi.c's header -- the panel is 4-wire MCU
 *     SPI with D/C on GPIO5, and that pad was being pinmuxed to
 *     QSPI1_IO1 instead of driven as a GPIO.
 *
 *  4. Wrong wire protocol.  Also bk7258_qspi.c: the QSPI-panel 4-byte
 *     header was being sent instead of bare opcode bytes.
 *
 * Two further gaps fixed here while at it: the previous table silently
 * dropped the {0x00, {0x78}, 0xFF} delay marker's neighbours and, more
 * importantly, never programmed CASET/RASET at init -- bk_lcd_spi_init()
 * ends by setting the drawing window to the full panel, and a GC9-series
 * panel's window registers have no guaranteed reset value.
 *
 * Success criterion note: GC9D01 exposes no readable ID register (there is
 * no RDID opcode anywhere in the vendor's table), so "the sequence was
 * sent without timing out" has never been evidence that the panel accepted
 * it.  The only proof is pixels on the glass.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <errno.h>

#include "bk7258_gpio.h"
#include "bk7258_ldo33.h"
#include "bk7258_qspi.h"
#include "bk7258_gc9d01_fb.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Pin assignments, all from AIDK_AI玩具开发板_原理图.pdf.  Sheet 2/6's
 * main-chip pin table maps pad -> net; sheet 5/6's LCD1 footprint (the one
 * labelled 单屏 / single screen, as opposed to LCD2 = 双屏) maps net ->
 * panel signal:
 *
 *   P45  -> LCD_RST     -> panel RESET
 *   P5   -> LCD_QSPI_D1 -> panel D/C
 *   P25  -> LCD_BL_PWM  -> Q3 base -> LCD_BL -> panel LEDK
 *   P52  -> LDO33_EN    -> LDO_3V3 -> panel VDD + LEDA
 *
 * GPIO45 was already correct.  The other three were missing entirely; the
 * D/C one was actively wrong (pinmuxed as a QSPI data line).
 */

#define GC9D01_RESET_PIN     45u
#define GC9D01_DC_PIN        5u
#define GC9D01_BACKLIGHT_PIN 25u

/* Time for LDO_3V3 to come up before the panel is touched.  No datasheet
 * citation; 20ms is generously above any small LDO's soft-start and costs
 * nothing once per boot.
 */

#define GC9D01_LDO_SETTLE_MS 20u

/* Delay-marker convention from the vendor table: data_len == 0xFF means
 * "this is not a command, delay data[0] milliseconds", handled by
 * bk_lcd_qspi_init()/bk_lcd_spi_init() rather than by the bus driver.
 */

#define GC9D01_DELAY_MARKER  0xFFu

struct gc9d01_init_cmd
{
  uint8_t cmd;
  uint8_t data[32];
  uint8_t data_len;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* All 50 entries of gc9d01_init_cmds, in order, including the delay marker
 * and the trailing Display On.  Earlier revisions of this file omitted 20
 * of them -- 11 because the old bus driver could not carry more than 4
 * payload bytes, and 9 with no stated reason -- which meant the panel's
 * gamma, porch and power-control registers were left at reset values.
 */

static const struct gc9d01_init_cmd g_gc9d01_init_cmds[] =
{
