  flags = enter_critical_section();
  modifyreg32(BK7258_PWM_CCMR, BK7258_PWM_CCMR_CH4E, 0);
  modifyreg32(BK7258_PWM_CR1, BK7258_PWM_CR1_CEN2, 0);
