#define BK7258_MOTOR_PWM_GPIO         9u
#define BK7258_GPIO_FUNC_PWM3         1u

/* GPIO52 used to be driven directly from here under the name
 * BK7258_MOTOR_LDO_GPIO, including an unconditional "drive low" in
 * bk7258_pwm_setup().  That pin is the board-wide LDO33_EN net, which also
 * supplies the LCD's VDD and backlight anode (see bk7258_ldo33.h): because
 * bk7258_motor_setup() runs before display bring-up in bk7258_bringup(),
 * the panel was permanently unpowered and every frame pushed to it was
 * invisible.  The rail is now reference counted; the motor takes a
 * reference only while it is actually driving.
 */

struct bk7258_pwm_lowerhalf_s
{
  const struct pwm_ops_s *ops;
  bool setup;
  bool ldo_held;
};

