/****************************************************************************
 * Name: bk7258_motor_ldo_hold
 *
 * Description:
 *   Take or drop this driver's single reference on the shared LDO33_EN
 *   rail.  Idempotent, so repeated pwm_start() calls do not leak
 *   references.  Must be called with the driver's critical section held
 *   (the refcount itself is separately protected, but ldo_held is not).
 *
 ****************************************************************************/

static void bk7258_motor_ldo_hold(struct bk7258_pwm_lowerhalf_s *priv,
                                  bool hold)
{
  if (hold == priv->ldo_held)
    {
      return;
    }

  if (hold)
    {
      bk7258_ldo33_request();
    }
  else
    {
      bk7258_ldo33_release();
    }

  priv->ldo_held = hold;
}

static int bk7258_pwm_setup(struct pwm_lowerhalf_s *dev)
{
  struct bk7258_pwm_lowerhalf_s *priv =
    (struct bk7258_pwm_lowerhalf_s *)dev;
  irqstate_t flags;

  flags = enter_critical_section();
  modifyreg32(BK7258_SYS_CLKSEL, 0, BK7258_SYS_PWM0_CLKSEL);
  modifyreg32(BK7258_SYS_CLK_ENABLE, 0, BK7258_SYS_PWM0_CLK_ENABLE);
  putreg32(1, BK7258_PWM_CG_RESET);
  bk7258_gpio_set_function(BK7258_MOTOR_PWM_GPIO, BK7258_GPIO_FUNC_PWM3);

  /* No rail manipulation here.  Setup runs at boot for every board, and
   * forcing LDO33_EN low was what kept the LCD dark.
   */

  priv->setup = true;
  leave_critical_section(flags);

  return OK;
}

