/****************************************************************************
 * board/beken/chips/bk7258/sim_tests/test_lcd_spi.c
 *
 * Desktop tests for bk7258_qspi.c (the 4-wire MCU-SPI LCD transport) and
 * bk7258_ldo33.c (the shared 3.3V rail refcount), compiling the real
 * production sources with register access redirected to mock memory.
 *
 * These tests exist because of a specific failure mode: the previous
 * version of this driver spoke the wrong panel protocol, and *every*
 * observable the driver itself produced said "success" -- commands
 * completed, the bus was busy for the right number of microseconds, the
 * frame counter advanced.  The only way to catch that class of bug without
 * a scope is to assert on the exact bytes and register values that reach
 * the wire, against the vendor reference's framing.  So that is what these
 * tests do.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

#include "sim_stubs.h"
#include "bk7258_qspi.h"
#include "bk7258_ldo33.h"
#include "hardware/bk7258_memorymap.h"
#include "hardware/bk7258_sysctrl.h"
#include "hardware/bk7258_gpio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define QSPI_REG(off)      (BK7258_QSPI1_BASE + (off))
#define QSPI_GLB_CTRL      QSPI_REG(0x08u)
#define QSPI_CMD_A_CFG2    QSPI_REG(0x2cu)
#define QSPI_CMD_C_L       QSPI_REG(0x40u)
#define QSPI_CMD_C_H       QSPI_REG(0x44u)
#define QSPI_CMD_C_CFG1    QSPI_REG(0x48u)
#define QSPI_CMD_C_CFG2    QSPI_REG(0x4cu)
#define QSPI_STATUS_CLR    QSPI_REG(0x6cu)
#define QSPI_STATUS        QSPI_REG(0x70u)
#define QSPI_CONFIG        QSPI_REG(0x60u)
#define QSPI_FIFO_DATA     QSPI_REG(0x100u)
#define QSPI1_DATA_WINDOW  0x68000000u

#define QSPI_CONFIG_QSPI_EN          (1u << 0)
#define QSPI_CONFIG_IO2_IO3_MODE     (1u << 3)
#define QSPI_CONFIG_FORCE_CS_LOW     (1u << 6)
#define QSPI_CONFIG_CLK_RATE_MASK    (0xffu << 8)
#define QSPI_CONFIG_DISABLE_CMD_SCK  (1u << 16)
#define QSPI_CONFIG_IO_CPU_MEM_SEL   (1u << 22)

#define DC_PIN 5u
#define DC_CFG BK7258_GPIO_CFG(DC_PIN)

/* Pads the controller must own, and the one it must not. */

#define CLK_CFG BK7258_GPIO_CFG(2u)
#define CSN_CFG BK7258_GPIO_CFG(3u)
#define IO0_CFG BK7258_GPIO_CFG(4u)

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Recorded wire event: one command-channel transfer, or one DC change. */

enum evt_e
{
  EVT_DC,        /* value = new DC level */
  EVT_XFER,      /* cmd_c_h / cfg1 / cfg2 snapshot at cmd_start */
  EVT_WINDOW     /* value = word written to the data window */
};

struct evt_s
{
  enum evt_e kind;
  uint32_t value;
  uint32_t cmd_c_h;
  uint32_t cfg1;
  uint32_t cfg2;
  uintptr_t addr;
};

#define MAX_EVENTS 4096

static struct evt_s g_events[MAX_EVENTS];
static unsigned int g_nevents;
static bool g_dc_level;
static int g_failures;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

#define CHECK(cond, ...)                                     \
  do                                                         \
    {                                                        \
      if (!(cond))                                           \
        {                                                    \
          printf("  FAIL %s:%d: ", __func__, __LINE__);       \
          printf(__VA_ARGS__);                                \
          printf("\n");                                      \
          g_failures++;                                      \
        }                                                    \
    }                                                        \
  while (0)

static void evt_push(struct evt_s e)
{
  if (g_nevents < MAX_EVENTS)
    {
      g_events[g_nevents++] = e;
    }
}

/* The controller never asserts cmd_start_done on its own in this harness,
 * so the read hook fakes an instantly-completing controller.  That is the
 * correct simulation: these tests are about what bytes are programmed, not
 * about the wait loop (which test_qspi_timeout covers separately by
 * leaving the hook off).
 */

static uint32_t read_hook(uintptr_t addr, uint32_t stored, void *arg)
{
  (void)arg;

  if (addr == QSPI_STATUS)
    {
      return stored | (1u << 2);
    }

  return stored;
}

static void write_hook(uintptr_t addr, uint32_t value, void *arg)
{
  (void)arg;

  if (addr == DC_CFG)
    {
      bool level = (value & BK7258_GPIO_OUTPUT) != 0;

      if (level != g_dc_level)
        {
          struct evt_s e;

          memset(&e, 0, sizeof(e));
          e.kind = EVT_DC;
          e.value = level;
          evt_push(e);
          g_dc_level = level;
        }
    }
  else if (addr == QSPI_CMD_C_CFG2 && (value & 1u) != 0)
    {
      struct evt_s e;

      memset(&e, 0, sizeof(e));
      e.kind = EVT_XFER;
      e.cmd_c_h = bk7258_sim_peek32(QSPI_CMD_C_H);
      e.cfg1 = bk7258_sim_peek32(QSPI_CMD_C_CFG1);
      e.cfg2 = value;
      evt_push(e);
    }
  else if (addr >= QSPI1_DATA_WINDOW && addr < QSPI1_DATA_WINDOW + 0x100000u)
    {
      struct evt_s e;

      memset(&e, 0, sizeof(e));
      e.kind = EVT_WINDOW;
      e.value = value;
      e.addr = addr;
      evt_push(e);
    }
}

static void harness_reset(void)
{
  bk7258_sim_reset();
  g_nevents = 0;

  /* Mirror the driver's post-init DC state (idle high) so the first
   * command's DC-low transition is recorded.
   */

  g_dc_level = false;
  bk7258_sim_set_read_hook(read_hook, NULL);
  bk7258_sim_set_write_hook(write_hook, NULL);
}

static void init_bus(void)
{
  harness_reset();
  bk7258_lcd_spi_init(DC_PIN);
  g_nevents = 0;
  g_dc_level = true;
}

/****************************************************************************
 * Tests
 ****************************************************************************/

static void test_init_pinmux_leaves_dc_as_gpio(void)
{
  uint32_t dc;

  harness_reset();
  bk7258_lcd_spi_init(DC_PIN);

  /* CLK/CSN/IO0 must be handed to the controller ... */

  CHECK((bk7258_sim_peek32(CLK_CFG) & BK7258_GPIO_SECOND_FUNCTION) != 0,
        "GPIO2 not switched to second function");
  CHECK((bk7258_sim_peek32(CSN_CFG) & BK7258_GPIO_SECOND_FUNCTION) != 0,
        "GPIO3 not switched to second function");
  CHECK((bk7258_sim_peek32(IO0_CFG) & BK7258_GPIO_SECOND_FUNCTION) != 0,
        "GPIO4 not switched to second function");

  /* ... and GPIO5 must NOT be, because it is the panel's D/C input.
   * Pinmuxing it as QSPI1_IO1 is the original bug.
   */

  dc = bk7258_sim_peek32(DC_CFG);
  CHECK((dc & BK7258_GPIO_SECOND_FUNCTION) == 0,
        "GPIO5 was pinmuxed as QSPI1_IO1 (cfg=0x%08x); it is the D/C line",
        dc);
  CHECK((dc & BK7258_GPIO_OUTPUT) != 0,
        "GPIO5 not driven high (idle = data) after init, cfg=0x%08x", dc);
}

static void test_init_clocks_and_controller(void)
{
  uint32_t devclk;
  uint32_t clkdiv;
  uint32_t config;

  harness_reset();
  bk7258_lcd_spi_init(DC_PIN);

  devclk = bk7258_sim_peek32(BK7258_SYS_DEVCLK_EN);
  CHECK((devclk & BK7258_QSPI1_MODULE_CLK_EN) != 0,
        "QSPI1 module clock gate not enabled (devclk=0x%08x)", devclk);

  clkdiv = bk7258_sim_peek32(BK7258_SYS_CPU26M_WDT_CLKDIV);
  CHECK((clkdiv & BK7258_QSPI1_CKSEL_480M) != 0,
        "QSPI1 source not set to 480MHz (clkdiv=0x%08x)", clkdiv);
  CHECK(((clkdiv & BK7258_QSPI1_CKDIV_MASK) >> BK7258_QSPI1_CKDIV_SHIFT) == 7,
        "QSPI1 pre-divider not 7 (=> 60MHz), clkdiv=0x%08x", clkdiv);

  config = bk7258_sim_peek32(QSPI_CONFIG);
  CHECK((config & QSPI_CONFIG_QSPI_EN) != 0, "qspi_en not set");
  CHECK((config & QSPI_CONFIG_IO2_IO3_MODE) != 0, "io2_io3_mode not set");
  CHECK((config & QSPI_CONFIG_CLK_RATE_MASK) == 0,
        "config.clk_rate must stay 0 (division happens in sysctrl), "
        "config=0x%08x", config);

  /* Final soft_reset state is 1, matching lcd_spi_driver_init_with_qspi()'s
   * disable -> delay -> enable order.
   */

  CHECK((bk7258_sim_peek32(QSPI_GLB_CTRL) & 1u) != 0,
        "glb_ctrl.soft_reset should end at 1, got 0x%08x",
        bk7258_sim_peek32(QSPI_GLB_CTRL));

  CHECK(bk7258_sim_peek32(QSPI_CMD_A_CFG2) == 0x80000000u,
        "cmd_a_cfg2 mapping-mode value not installed, got 0x%08x",
        bk7258_sim_peek32(QSPI_CMD_A_CFG2));
}

static void test_command_is_bare_opcode_with_dc_low(void)
{
  init_bus();

  CHECK(bk7258_lcd_spi_write_cmd(0xFE), "write_cmd failed");

  CHECK(g_nevents == 2, "expected DC-low then one transfer, got %u events",
        g_nevents);

  if (g_nevents >= 2)
    {
      CHECK(g_events[0].kind == EVT_DC && g_events[0].value == 0,
            "DC was not driven low before the opcode");
      CHECK(g_events[1].kind == EVT_XFER, "second event is not a transfer");

      /* The whole point: a bare opcode in cmd1, not a
       * {0x02, 0x00, reg, 0x00} header.
       */

      CHECK(g_events[1].cmd_c_h == 0xFEu,
            "cmd_c_h should be the bare opcode 0xFE, got 0x%08x",
            g_events[1].cmd_c_h);
      CHECK(g_events[1].cfg1 == (0x3u << 2),
            "cfg1 should mark end after 1 byte (0x%x), got 0x%08x",
            0x3u << 2, g_events[1].cfg1);
      CHECK(bk7258_sim_peek32(QSPI_CMD_C_L) == 0,
            "cmd_c_l must stay 0 in MCU-SPI framing, got 0x%08x",
            bk7258_sim_peek32(QSPI_CMD_C_L));
    }
}

static void test_short_payload_packs_into_cmd_c_h(void)
{
  static const uint8_t args[4] =
  {
    0x00, 0x00, 0x00, 0x9f
  };

  init_bus();

  CHECK(bk7258_lcd_spi_write_cmd_data(0x2A, args, 4), "cmd+data failed");

  /* DC low, opcode, DC high, 4 payload bytes in one transfer. */

  CHECK(g_nevents == 4, "expected 4 events, got %u", g_nevents);

  if (g_nevents >= 4)
    {
      CHECK(g_events[0].kind == EVT_DC && g_events[0].value == 0,
            "no DC-low before opcode");
      CHECK(g_events[1].cmd_c_h == 0x2Au, "opcode wrong: 0x%08x",
            g_events[1].cmd_c_h);
      CHECK(g_events[2].kind == EVT_DC && g_events[2].value == 1,
            "DC was not raised before the parameter bytes");

      /* Little-endian pack so cmd1 == data[0]: 0x9f000000. */

      CHECK(g_events[3].cmd_c_h == 0x9f000000u,
            "payload pack wrong, expected 0x9f000000 got 0x%08x",
            g_events[3].cmd_c_h);
      CHECK(g_events[3].cfg1 == (0x3u << 8),
            "cfg1 should mark end after 4 bytes (0x300), got 0x%08x",
            g_events[3].cfg1);
    }
}

static void test_long_payload_uses_fifo(void)
{
  uint8_t args[32];
  unsigned int i;
  unsigned int xfers = 0;

  for (i = 0; i < sizeof(args); i++)
    {
      args[i] = (uint8_t)(i + 1);
    }

  init_bus();

  /* 0x6E's 32-byte payload is the longest entry in the GC9D01 table and
   * the one the old 4-byte-limited bus driver could not send at all.
   */

  CHECK(bk7258_lcd_spi_write_cmd_data(0x6E, args, sizeof(args)),
        "32-byte payload failed");

  for (i = 0; i < g_nevents; i++)
    {
      if (g_events[i].kind == EVT_XFER)
        {
          xfers++;
        }
    }

  /* One transfer for the opcode, one for all 32 payload bytes (4 in
   * cmd_c_h + 28 in the FIFO, which fits the 244-byte FIFO).
   */

  CHECK(xfers == 2, "expected 2 transfers (opcode + payload), got %u",
        xfers);

  if (g_nevents >= 4)
    {
      struct evt_s *pay = &g_events[g_nevents - 1];

      CHECK(pay->cmd_c_h == 0x04030201u,
            "first 4 payload bytes wrong: 0x%08x", pay->cmd_c_h);
      CHECK(pay->cfg1 == 0x300u, "cfg1 should be 0x300 for a FIFO payload, "
            "got 0x%08x", pay->cfg1);
      CHECK(pay->cfg2 == ((28u << 2) | 1u),
            "cfg2 should carry data_len=28 plus cmd_start, got 0x%08x",
            pay->cfg2);

      /* FIFO word 0 = bytes 5,6,7,8 of the payload. */

      CHECK(bk7258_sim_peek32(QSPI_FIFO_DATA) == 0x08070605u,
            "FIFO word 0 wrong: 0x%08x",
            bk7258_sim_peek32(QSPI_FIFO_DATA));
    }
}

static void test_frame_burst_shape(void)
{
  static uint32_t frame[8];
  unsigned int i;
  unsigned int windows = 0;
  unsigned int xfers = 0;
  int ramwr_idx = -1;
  uint32_t config;

  for (i = 0; i < 8; i++)
    {
      frame[i] = 0xf800f800u;
    }

  init_bus();

  CHECK(bk7258_lcd_spi_write_frame(frame, sizeof(frame)),
        "frame push failed");

  for (i = 0; i < g_nevents; i++)
    {
      if (g_events[i].kind == EVT_XFER)
        {
          xfers++;
          if (g_events[i].cmd_c_h == 0x2Cu)
            {
              ramwr_idx = (int)i;
            }
        }
      else if (g_events[i].kind == EVT_WINDOW)
        {
          windows++;
        }
    }

  /* Exactly one command-channel transfer: RAMWR as a bare opcode.  The old
   * driver instead sent a {0x02, 0x00, 0x2C, 0x00} header here.
   */

  CHECK(xfers == 1, "expected exactly 1 command transfer (RAMWR), got %u",
        xfers);
  CHECK(ramwr_idx >= 0, "RAMWR (0x2C) was never sent as a bare opcode");

  if (ramwr_idx >= 0)
    {
      CHECK(g_events[ramwr_idx].cfg1 == (0x3u << 2),
            "RAMWR cfg1 wrong: 0x%08x", g_events[ramwr_idx].cfg1);
      CHECK(ramwr_idx > 0 && g_events[ramwr_idx - 1].kind == EVT_DC &&
            g_events[ramwr_idx - 1].value == 0,
            "RAMWR was not preceded by DC low");
    }

  CHECK(windows == 8, "expected 8 window writes, got %u", windows);

  /* Destination address must advance: the reference DMA config sets
   * dst.addr_inc_en = DMA_ADDR_INC_ENABLE with end = start + data_len.
   */

  if (windows == 8)
    {
      unsigned int seen = 0;

      for (i = 0; i < g_nevents; i++)
        {
          if (g_events[i].kind == EVT_WINDOW)
            {
              CHECK(g_events[i].addr == QSPI1_DATA_WINDOW + seen * 4u,
                    "window write %u went to 0x%lx, expected 0x%lx",
                    seen, (unsigned long)g_events[i].addr,
                    (unsigned long)(QSPI1_DATA_WINDOW + seen * 4u));
              seen++;
            }
        }
    }

  /* All three burst-mode bits must be released afterwards, or the next
   * command would be clocked out with CS stuck low and no SCK.
   */

  config = bk7258_sim_peek32(QSPI_CONFIG);
  CHECK((config & QSPI_CONFIG_FORCE_CS_LOW) == 0, "force_spi_cs_low stuck");
  CHECK((config & QSPI_CONFIG_IO_CPU_MEM_SEL) == 0, "io_cpu_mem_sel stuck");
  CHECK((config & QSPI_CONFIG_DISABLE_CMD_SCK) == 0, "disable_cmd_sck stuck");

  CHECK(bk7258_lcd_spi_frame_count() > 0, "frame counter did not advance");
}

static void test_frame_rejects_bad_length(void)
{
  static uint32_t frame[4];

  init_bus();

  CHECK(!bk7258_lcd_spi_write_frame(NULL, 16), "NULL frame accepted");
  CHECK(!bk7258_lcd_spi_write_frame(frame, 0), "zero length accepted");
  CHECK(!bk7258_lcd_spi_write_frame(frame, 15),
        "non-multiple-of-4 length accepted");
}

static void test_timeout_is_reported(void)
{
  harness_reset();
  bk7258_lcd_spi_init(DC_PIN);

  /* Drop the read hook so cmd_start_done never asserts, i.e. simulate a
   * controller that is not running.  The driver must give up rather than
   * hang, and must report the failure.
   */

  bk7258_sim_set_read_hook(NULL, NULL);

  CHECK(!bk7258_lcd_spi_write_cmd(0xFE),
        "write_cmd claimed success while cmd_start_done never asserted");
}

static void test_ldo33_refcount(void)
{
  uint32_t cfg = BK7258_GPIO_CFG(BK7258_LDO33_EN_GPIO);

  harness_reset();

  CHECK(bk7258_ldo33_refcount() == 0 ||
        bk7258_ldo33_refcount() > 0,
        "refcount unreadable");

  /* Drain whatever a previous test left behind so this test is order
   * independent (the refcount is process-global static state).
   */

  while (bk7258_ldo33_refcount() > 0)
    {
      bk7258_ldo33_release();
    }

  CHECK(bk7258_ldo33_request() == 1, "first request should return 1");
  CHECK((bk7258_sim_peek32(cfg) & BK7258_GPIO_OUTPUT) != 0,
        "rail not driven high on first request, cfg=0x%08x",
        bk7258_sim_peek32(cfg));

  CHECK(bk7258_ldo33_request() == 2, "second request should return 2");
  CHECK(bk7258_ldo33_release() == 1, "release should return 1");

  /* Still one holder (the display), so the rail must stay on even though
   * the other consumer (the motor) let go.  This is the exact regression:
   * the motor driver used to drive this pin low unconditionally.
   */

  CHECK((bk7258_sim_peek32(cfg) & BK7258_GPIO_OUTPUT) != 0,
        "rail dropped while a reference was still held");

  CHECK(bk7258_ldo33_release() == 0, "final release should return 0");
  CHECK((bk7258_sim_peek32(cfg) & BK7258_GPIO_OUTPUT) == 0,
        "rail not turned off after last release");

  /* Underflow must not wrap. */

  CHECK(bk7258_ldo33_release() == 0, "release below zero must stay 0");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(void)
{
  struct
  {
    const char *name;
    void (*fn)(void);
  }
