 *   RGB565, straight from the capture buffer into the framebuffer.
 *
 *   YUYV (yuyv422) packs two pixels per 4 bytes as Y0 U Y1 V, so a source
 *   x maps to quad (x >> 1) and picks Y0 (byte 0) or Y1 (byte 2) by x's
 *   parity, with U at byte 1 and V at byte 3 shared by both pixels.
 *   BT.601 coefficients are used in 8-bit fixed point; the shifts are
 *   chosen so the whole conversion stays in 32-bit integer math.
 *
 *   CORRECTION (2026-08-10): this used to decode UYVY (U Y0 V Y1), matching
 *   what the imgsensor driver advertised at the time.  Both were wrong in
 *   the same direction, so V4L2 format negotiation succeeded and nothing
 *   reported an error -- but luma and chroma were swapped, which renders as
 *   high-frequency colour noise with no recognisable subject.  The hardware
 *   writes YUYV; see the byte-level evidence in
 *   bk7258_camera_imgsensor.c's g_bk7258_gc2145_fmtdescs comment.
 *
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct preview_s p;
  struct fb_area_s area;
  struct v4l2_buffer buf;
  int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  uint32_t max_frames = 0;
  uint32_t frames = 0;
  uint32_t errors = 0;
  uint32_t conv_ms = 0;
  uint32_t push_ms = 0;
  uint32_t t_start;
  uint32_t t0;
  bool pattern_mode = false;
  int ret;

  if (argc > 1)
    {
      if (strcmp(argv[1], "fill") == 0 || strcmp(argv[1], "bars") == 0 ||
          strcmp(argv[1], "grid") == 0 || strcmp(argv[1], "pattern") == 0)
        {
          pattern_mode = true;
        }
      else
        {
          max_frames = (uint32_t)atoi(argv[1]);
