static void test_frame_byteswap(void)
{
  static uint32_t frame[4];
  unsigned int i;
  uint32_t got[4];
  unsigned int n = 0;

  /* Two RGB565 pixels per word, little-endian in memory as NuttX's
   * FB_FMT_RGB16_565 requires: 0xf800 (red) then 0x001f (blue).
   */

  frame[0] = 0x001ff800u;
  frame[1] = 0x001ff800u;
  frame[2] = 0x001ff800u;
  frame[3] = 0x001ff800u;

  /* Default: swap on.  The panel takes the high byte of each pixel first,
   * so each halfword must come out byte-reversed.
   */

  init_bus();
  bk7258_lcd_spi_set_byteswap(true);
  CHECK(bk7258_lcd_spi_get_byteswap(), "byteswap accessor did not stick");
  CHECK(bk7258_lcd_spi_write_frame(frame, sizeof(frame)), "frame failed");

  for (i = 0; i < g_nevents && n < 4; i++)
    {
      if (g_events[i].kind == EVT_WINDOW)
        {
          got[n++] = g_events[i].value;
        }
    }

  CHECK(n == 4, "expected 4 window writes, got %u", n);
  if (n == 4)
    {
      /* 0x001ff800 -> halfwords 0xf800,0x001f -> swapped 0x00f8,0x1f00
       * -> packed back little-endian as 0x1f0000f8.
       */

      CHECK(got[0] == 0x1f0000f8u,
            "swapped word wrong: expected 0x1f0000f8 got 0x%08x", got[0]);
    }

  /* Swap off: bytes must pass through untouched, so the switch is a real
   * switch and not a no-op.
   */

  init_bus();
  bk7258_lcd_spi_set_byteswap(false);
  CHECK(bk7258_lcd_spi_write_frame(frame, sizeof(frame)), "frame failed");

  n = 0;
  for (i = 0; i < g_nevents && n < 4; i++)
    {
      if (g_events[i].kind == EVT_WINDOW)
        {
          got[n++] = g_events[i].value;
        }
    }

  if (n == 4)
    {
      CHECK(got[0] == 0x001ff800u,
            "unswapped word altered: expected 0x001ff800 got 0x%08x",
            got[0]);
    }

  /* Leave the default as the production one so test order cannot change
   * what a later case observes.
   */

  bk7258_lcd_spi_set_byteswap(true);
}

