static void test_two_buses_are_independent(void)
{
  /* Bus 0 must drive the *other* controller and its own pads/clock
   * register.  Getting this wrong would silently make both /dev/fb nodes
   * push to the same panel, which on the glass looks like "the second
   * screen never works" -- indistinguishable from an unpopulated
   * footprint, since GC9D01 has no readable ID.
   */

  harness_reset();
  bk7258_lcd_spi_init(BK7258_LCD_BUS0, 7u);

  CHECK((bk7258_sim_peek32(BK7258_QSPI0_BASE + 0x60u) &
         QSPI_CONFIG_QSPI_EN) != 0,
        "bus 0 did not enable QSPI0 (config=0x%08x)",
        bk7258_sim_peek32(BK7258_QSPI0_BASE + 0x60u));

  CHECK(bk7258_sim_peek32(BK7258_QSPI1_BASE + 0x60u) == 0,
        "bus 0 init touched QSPI1's config (0x%08x)",
        bk7258_sim_peek32(BK7258_QSPI1_BASE + 0x60u));

  /* QSPI0's divider lives in a different sysctrl register than QSPI1's --
   * same bit positions, which is exactly why it is easy to write to the
   * wrong one.
   */

  CHECK((bk7258_sim_peek32(BK7258_SYS_CPU_CLKDIV_MODE2) &
         BK7258_QSPI0_CKSEL_480M) != 0,
        "bus 0 did not select 480MHz in CLKDIV_MODE2 (0x%08x)",
        bk7258_sim_peek32(BK7258_SYS_CPU_CLKDIV_MODE2));
  CHECK(((bk7258_sim_peek32(BK7258_SYS_CPU_CLKDIV_MODE2) &
          BK7258_QSPI0_CKDIV_MASK) >> BK7258_QSPI0_CKDIV_SHIFT) == 7,
        "bus 0 pre-divider not 7");
  CHECK(bk7258_sim_peek32(BK7258_SYS_CPU26M_WDT_CLKDIV) == 0,
        "bus 0 init wrote QSPI1's clock register (0x%08x)",
        bk7258_sim_peek32(BK7258_SYS_CPU26M_WDT_CLKDIV));

  /* Module clock gates are distinct bits of the same register. */

  CHECK((bk7258_sim_peek32(BK7258_SYS_DEVCLK_EN) &
         BK7258_QSPI0_MODULE_CLK_EN) != 0, "bus 0 clock gate not set");
  CHECK((bk7258_sim_peek32(BK7258_SYS_DEVCLK_EN) &
         BK7258_QSPI1_MODULE_CLK_EN) == 0,
        "bus 0 init enabled QSPI1's clock gate too");

  /* Bus 0 owns GPIO22/23/24; its D/C (GPIO7) must stay a plain GPIO, just
   * as GPIO5 must on bus 1.
   */

  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(22u)) &
         BK7258_GPIO_SECOND_FUNCTION) != 0, "GPIO22 not pinmuxed");
  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(23u)) &
         BK7258_GPIO_SECOND_FUNCTION) != 0, "GPIO23 not pinmuxed");
  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(24u)) &
         BK7258_GPIO_SECOND_FUNCTION) != 0, "GPIO24 not pinmuxed");
  CHECK((bk7258_sim_peek32(BK7258_GPIO_CFG(7u)) &
         BK7258_GPIO_SECOND_FUNCTION) == 0,
        "GPIO7 was pinmuxed; it is bus 0's D/C line");

  /* Bus 1's pads must be untouched by a bus 0 init. */

  CHECK(bk7258_sim_peek32(CLK_CFG) == 0,
        "bus 0 init touched GPIO2 (bus 1's CLK)");

  CHECK(bk7258_lcd_spi_ready(BK7258_LCD_BUS0), "bus 0 not marked ready");
  CHECK(!bk7258_lcd_spi_ready(BK7258_LCD_BUS1),
        "bus 1 reported ready after only bus 0 was initialized");
  CHECK(!bk7258_lcd_spi_ready(-1) && !bk7258_lcd_spi_ready(99),
        "out-of-range bus index accepted");
}

static void test_frame_count_is_per_bus(void)
{
  static uint32_t frame[4] = { 0, 0, 0, 0 };

  harness_reset();
  bk7258_lcd_spi_init(BK7258_LCD_BUS0, 7u);
  bk7258_lcd_spi_init(BK7258_LCD_BUS1, 5u);

  CHECK(bk7258_lcd_spi_write_frame(BK7258_LCD_BUS0, frame, sizeof(frame)),
        "bus 0 frame failed");

  CHECK(bk7258_lcd_spi_frame_count(BK7258_LCD_BUS0) == 1,
        "bus 0 frame count = %u, expected 1",
        bk7258_lcd_spi_frame_count(BK7258_LCD_BUS0));
  CHECK(bk7258_lcd_spi_frame_count(BK7258_LCD_BUS1) == 0,
        "bus 1 frame count moved when only bus 0 was pushed (%u)",
        bk7258_lcd_spi_frame_count(BK7258_LCD_BUS1));
}

