static int preview_convert(FAR struct preview_s *p, int index)
{
  FAR const uint8_t *src = p->bufs[index];
  int dw = p->vinfo.xres;
  int dh = p->vinfo.yres;
  int step = CROP_SIZE / dw;          /* 480 / 160 = 3 */
  int ycoef = g_full_range ? 256 : 298;
  int yoff  = g_full_range ? 0 : 16;
  int dx;
  int dy;
  int i;

  /* Byte offsets within the 4-byte group, by decode order. */

  int off_u  = (g_yuv_order == PREVIEW_UYVY) ? 0 : 1;
  int off_y0 = (g_yuv_order == PREVIEW_UYVY) ? 1 : 0;
  int off_v  = (g_yuv_order == PREVIEW_UYVY) ? 2 : 3;
  int off_y1 = (g_yuv_order == PREVIEW_UYVY) ? 3 : 2;

  /* Shift amounts for extracting those bytes out of one little-endian
   * 32-bit load.  Hoisted here because the decode order cannot change
   * within a frame.
   *
   * Reading the group as a single aligned word instead of three separate
   * byte accesses is the main cost saving in this function: the source
   * frame lives in PSRAM, which is mapped non-cacheable, so every byte
   * access is a full bus transaction.  Three per output pixel across
   * 25600 pixels was 76800 transactions per frame and measured 180ms --
   * more than three times the 55ms spent pushing both panels.  The three
   * bytes always live in the same word, so one load serves all of them.
   *
   * Alignment holds: srow advances by CAM_WIDTH*2 == 1280 (a multiple of
   * 4), the group offset is (sx >> 1) * 4, and the capture buffer itself is
   * PSRAM-pool allocated and word aligned.
   */

  int sh_u  = off_u * 8;
  int sh_v  = off_v * 8;
  int sh_y0 = off_y0 * 8;
  int sh_y1 = off_y1 * 8;

  /* Chroma gain folded into the BT.601 coefficients.  g_sat is constant for
   * the frame, so scaling it here removes two integer divisions per pixel
   * (51200 per frame) from the inner loop.
   */

  int c_rv;
  int c_gu;
  int c_gv;
  int c_bu;

  if (g_uv_swap)
    {
      int t = sh_u;

      sh_u = sh_v;
      sh_v = t;
    }

  ycoef = ycoef * g_gain / 100;

  c_rv = 409 * g_sat / 100;
  c_gu = 100 * g_sat / 100;
  c_gv = 208 * g_sat / 100;
  c_bu = 516 * g_sat / 100;

  if (step < 1 || dh * step > CAM_HEIGHT)
    {
      printf("preview: %dx%d panel does not divide the %dx%d crop\n",
             dw, dh, CROP_SIZE, CROP_SIZE);
      return -EINVAL;
    }

  for (dy = 0; dy < dh; dy++)
    {
      FAR const uint8_t *srow = src + (size_t)(dy * step) * CAM_WIDTH * 2;
      FAR uint16_t *drow = (FAR uint16_t *)(p->fbmem[0] +
                                            (size_t)dy * p->pinfo.stride);

      for (dx = 0; dx < dw; dx++)
        {
          int sx = CROP_X + dx * step;
          uint32_t quad = *(FAR const uint32_t *)(srow +
                                                  (size_t)(sx >> 1) * 4);
          int u = (int)((quad >> sh_u) & 0xff) - 128;
          int v = (int)((quad >> sh_v) & 0xff) - 128;
          int y = (int)((quad >> ((sx & 1) ? sh_y1 : sh_y0)) & 0xff) - yoff;
          int r;
          int g;
          int b;

          if (y < 0)
            {
              y = 0;
            }

          y *= ycoef;

          r = (y + c_rv * v + 128) >> 8;
          g = (y - c_gu * u - c_gv * v + 128) >> 8;
          b = (y + c_bu * u + 128) >> 8;

          r = r < 0 ? 0 : (r > 255 ? 255 : r);
          g = g < 0 ? 0 : (g > 255 ? 255 : g);
          b = b < 0 ? 0 : (b > 255 ? 255 : b);

          drow[dx] = (uint16_t)(((r & 0xf8) << 8) |
                                ((g & 0xfc) << 3) |
                                 (b >> 3));
        }
    }

